INSERT INTO products (product_id, product_name, description, price, stock_quantity, sub_category, category_id) VALUES
    (1, 'SavvySound Pro ANC Headphones', 'Over-ear wireless headphones with active noise cancellation, 40-hour battery life, and high-fidelity 40mm dynamic drivers.', 3499.00, 33, NULL, 1),
    (2, 'PulseFit Titan Smartwatch', '1.96-inch AMOLED display, all-day heart rate & SpO2 monitoring, IP68 water resistance, and 100+ fitness modes.', 2299.00, 50, NULL, 1),
    (3, 'Tactile Mechanical Keyboard RGB', 'Custom tactile switches, premium aluminum frame, customizable RGB backlighting, and braided USB-C cable.', 2899.00, 20, NULL, 1),
    (4, 'Urban Classic Heavyweight Hoodie', '100% organic French terry cotton with relaxed fit, kangaroo pocket, and double-lined hood for everyday warmth.', 1499.00, 45, NULL, 2),
    (5, 'Polarized Aviator Sunglasses', 'Timeless stainless steel aviator frame with polarized UV400 protective lenses and scratch-resistant coating.', 899.00, 60, NULL, 2),
    (6, 'Barista Artisan Stovetop Espresso Maker', 'Traditional 6-cup Moka espresso pot made from food-grade stainless steel with cool-touch ergonomic handle.', 1299.00, 28, NULL, 3),
    (7, 'Nordic Ceramic Dinnerware Set (16 Pcs)', 'Matte glaze stoneware dining set including 4 dinner plates, 4 salad plates, 4 cereal bowls, and 4 mugs.', 3999.00, 15, NULL, 3),
    (8, 'Executive Leather Hardcover Journal & Pen', '192 pages of bleed-resistant 100gsm acid-free cream paper, numbered pages, ribbon bookmark, with matching rollerball pen.', 699.00, 80, NULL, 4),
    (9, 'ProGrip Non-Slip Eco Yoga Mat (6mm)', 'High-density natural rubber and TPE dual-layer exercise mat with body alignment lines and carrying strap.', 1199.00, 40, NULL, 5),
    (10, 'Apple MacBook Air M2 (13.6-inch, 8GB RAM, 256GB SSD, Midnight)', 'Apple M2 chip with 8-core CPU and 8-core GPU. 13.6-inch Liquid Retina display with True Tone. 8GB unified memory, 256GB superfast SSD storage. Backlit Magic Keyboard with Touch ID, 1080p FaceTime HD camera, MagSafe 3 charging port.', 89990.00, 15, 'Laptops', 1),
    (11, 'ASUS TUF Gaming A15 AMD Ryzen 7 7735HS Gaming Laptop', '15.6-inch FHD (1920 x 1080) 144Hz IPS-level anti-glare display. AMD Ryzen 7 7735HS Processor with NVIDIA GeForce RTX 3050 4GB GDDR6 graphics. 16GB DDR5 RAM, 512GB PCIe 4.0 NVMe SSD, RGB Backlit Keyboard, Windows 11 Home.', 69990.00, 20, 'Laptops', 1),
    (12, 'Lenovo IdeaPad Slim 3 12th Gen Intel Core i5 Thin & Light Laptop', '15.6-inch FHD Anti-Glare display (250 nits). Intel Core i5-12450H 12th Gen processor, 16GB LPDDR5 RAM, 512GB SSD. Arctic Grey, 1.62 kg, Dolby Audio stereo speakers, rapid charge technology.', 52990.00, 25, 'Laptops', 1),
    (13, 'Apple iPad 10th Gen (10.9-inch Liquid Retina, A14 Bionic, 64GB Wi-Fi)', '10.9-inch Liquid Retina display with True Tone. A14 Bionic chip with 6-core CPU and 4-core GPU. 12MP Wide back camera, landscape 12MP Ultra Wide front camera with Center Stage, Touch ID, USB-C connectivity.', 34900.00, 30, 'Tablets', 1),
    (14, 'Xiaomi Pad 6 (11-inch 2.8K 144Hz Display, Snapdragon 870, 8GB/256GB)', 'Snapdragon 870 Octa-Core Processor, 8GB LPDDR5 RAM, 256GB UFS 3.1 storage. 11-inch 2.8K Crystal Clear display with 144Hz refresh rate, Dolby Vision Atmos, quad speakers, 8840mAh high capacity battery.', 24999.00, 28, 'Tablets', 1),
    (15, 'Philips OneBlade Face & Body Trimmer and Shaver QP2824', 'Unique OneBlade dual protection technology with fast cutter (12000x per minute). Shave, trim, and edge any length of hair. Waterproof IPX7, 45 minutes runtime on single USB-A charge, includes skin guard and body comb.', 1899.00, 40, 'Grooming', 1),
    (16, 'Spigen Liquid Air Armor Back Cover for iPhone 15', 'Modern geometric pattern with matte finish. Air Cushion Technology for anti-shock military drop protection. Raised bezels lift screen and camera off flat surfaces, wireless charging compatible.', 1299.00, 60, 'Mobile covers', 1),
    (17, 'Logitech MK295 Silent Wireless Keyboard and Mouse Combo', 'SilentTouch technology removes over 90% of clicking and typing noise without losing click feel. Full-size keyboard with 8 handy shortcuts, 24-month keyboard and 18-month mouse battery life, lag-free 2.4GHz wireless.', 2295.00, 45, 'Accessories', 1),
    (18, 'Mi 20000mAh Power Bank 3i with 18W Fast Charging', 'High-density Lithium Polymer battery with 18W fast charging output. Triple port output allows simultaneous charging of 3 devices. Dual input (Type-C and Micro-USB), 12-layer advanced circuit chip protection.', 2099.00, 55, 'Power Bank', 1),
    (19, 'Sony PlayStation 5 Console (Slim Disc Edition)', 'PlayStation 5 Slim model with 1TB ultra-high speed SSD storage. Ray tracing support, 4K-TV gaming up to 120fps, HDR technology, Tempest 3D AudioTech, DualSense wireless controller with haptic feedback and adaptive triggers.', 54990.00, 12, 'Gaming', 1),
    (20, 'TP-Link Tapo C210 2K 3MP Pan/Tilt Smart Security Wi-Fi Camera', 'Ultra-High-Definition 2K (3MP) video resolution. 360-degree horizontal and 114-degree vertical range. Advanced night vision up to 30 ft, motion detection and alerts, two-way audio, supports microSD card up to 256GB.', 2199.00, 35, 'Smart home Nav', 1),
    (21, 'TP-Link Archer AX12 Wi-Fi 6 Dual-Band Gigabit Router', 'Next-gen Wi-Fi 6 speeds up to 1.5 Gbps (1201 Mbps on 5 GHz and 300 Mbps on 2.4 GHz band). OFDMA and MU-MIMO technology connects more devices simultaneously with reduced lag. 4 high-gain antennas with Beamforming.', 2999.00, 40, 'Networking', 1),
    (22, 'JBL Cinema SB271 2.1 Channel Soundbar with Wireless Subwoofer (220W)', '220 Watts powerful audio output with dedicated wireless subwoofer delivering deep bass. Dolby Digital embedded, HDMI ARC and Optical cable connectivity, Bluetooth 5.1 wireless streaming.', 12999.00, 18, 'Speakers', 1),
    (23, 'Sony WH-1000XM5 Wireless Industry Leading Noise Cancelling Headphones', 'Two processors and 8 microphones for unprecedented active noise cancellation. Auto NC Optimizer, specially designed 30mm driver unit, crystal clear hands-free calling with 4 beamforming microphones, up to 30 hours battery life.', 29990.00, 22, 'Earphones', 1),
    (24, 'boAt Airdopes 141 Bluetooth Truly Wireless Earbuds', 'Up to 42 hours of total playback time with 6 hours uninterrupted playtime per charge. 8mm drivers deliver boAt Signature Sound. BEAST Mode for real-time low latency gaming, ENx Environmental Noise Cancellation technology, IPX4 sweat proof.', 1299.00, 75, 'Earphones', 1),
    (25, 'Samsung Galaxy Watch 4 Bluetooth (44mm, Super AMOLED)', 'Body Composition Analysis with Samsung BioActive Sensor. Comprehensive sleep tracker with blood oxygen level monitoring. Wear OS Powered by Samsung, 90+ workout tracking modes, optical heart rate sensor.', 9999.00, 25, 'Wearables', 1),
    (26, 'Noise ColorFit Pro 4 Alpha 1.78 inch AMOLED Calling Smartwatch', '1.78-inch AMOLED display with 368*448 high resolution and 500 nits brightness. Tru Sync Bluetooth calling technology, functional digital crown, 100 sports modes, Noise Health Suite with SpO2 and 24/7 heart rate monitor.', 2499.00, 50, 'Wearables', 1),
    (27, 'Ola S1 X Electric Scooter (2 kWh Battery, 95 km Range)', 'Eco-friendly electric mobility with 6 kW peak motor power. 85 km/h top speed, 3 riding modes (Eco, Normal, Sports), 3.5-inch LCD display, physical key unlock, combined braking system.', 74999.00, 8, '2 Wheelers', 1),
    (28, 'Logitech MX Master 3S Wireless Performance Ergonomic Mouse', 'Quiet Clicks with 90% less noise. 8K DPI any-surface tracking, MagSpeed electromagnetic scrolling wheels capable of 1,000 lines per second. USB-C rechargeable, pairs up to 3 computers across Windows and macOS.', 8995.00, 20, 'ITPeripherals', 1),
    (29, 'Anker 67W GaN 3-Port Fast Charger (2 USB-C + 1 USB-A)', 'GaNPrime intelligent power allocation technology. Fast charge MacBook Air, iPhone, and iPad simultaneously. 51% smaller than original 67W charger, ActiveShield 2.0 safety temperature monitoring system.', 3499.00, 40, 'Chargers & Cables', 1),
    (30, 'Insta360 X3 Waterproof 360 Action Camera 5.7K 360 Video', 'Dual 1/2-inch 48MP sensors capture 5.7K 360-degree Active HDR video and 72MP 360 photos. Invisible selfie stick effect for third-person drone-like shots. 2.29-inch tempered glass touchscreen, waterproof up to 10m (33ft).', 37990.00, 10, 'Camera', 1),
    (31, 'SanDisk Extreme 1TB Portable External NVMe SSD (Up to 1050MB/s)', 'Fast NVMe solid state performance in a portable, high-capacity rugged drive. Up to 1050MB/s read and 1000MB/s write speeds. Up to 2-meter drop protection and IP55 water and dust resistance, USB-C interface.', 11999.00, 30, 'Storage', 1),
    (32, 'Dr Trust USA Professional Acupressure Deep Tissue Massage Gun', 'Cordless handheld percussion massager with high-torque brushless motor. 6 intensity speed settings and 6 interchangeable massage heads for targeted myofascial relief, 4000mAh rechargeable lithium battery.', 2999.00, 35, 'Healthcare', 1),
    (33, 'Apple iPhone 15 (128 GB) - Black', 'Dynamic Island bubbles up alerts and Live Activities. 48MP Main camera with 2x Telephoto. Durable color-infused glass and aluminum design. A16 Bionic chip, USB-C charging with all-day battery life.', 69999.00, 15, 'Tech drop', 1),
    (34, 'Samsung Galaxy S24 Ultra 5G (Titanium Gray, 256GB)', 'Galaxy AI features Circle to Search, Live Translate, and Photo Assist. 200MP camera system with 5x optical zoom, Snapdragon 8 Gen 3 for Galaxy, 6.8-inch Dynamic AMOLED 2X flat display with Corning Gorilla Armor.', 129999.00, 10, 'Tech drop', 1),
    (35, 'Biba Women Cotton Straight Printed Kurta Set with Palazzo & Dupatta', 'Pure cotton ethnic kurta set featuring intricate floral block print, round neck with notch, three-quarter sleeves, matched with straight cotton palazzos and a lightweight chiffon bordered dupatta.', 2499.00, 40, 'Kurta sets', 6),
    (36, 'Libas Women Ethnic Embroidered Rayon Anarkali Kurta Set', 'Flared Anarkali kurta crafted from premium soft rayon with delicate zari work on the yoke, paired with comfortable churidar pants and gold-foiled dupatta. Ideal for festive gatherings and ceremonies.', 1799.00, 35, 'Kurta sets', 6),
    (37, 'Forever New Women Floral Print Tiered Fit & Flare Midi Dress', 'Elegant pastel floral tiered midi dress with V-neckline, self-tie fabric waist belt, flutter short sleeves, and flowy silhouette lined with breathable viscose fabric.', 4400.00, 20, 'Dresses', 6),
    (38, 'Wildcraft 35L Water-Resistant Laptop Backpack with Rain Cover', 'Three spacious zippered compartments with dedicated padded sleeve for up to 15.6-inch laptops. Ergonomic contoured shoulder straps with air mesh padding and integrated waterproof rain cover in bottom pouch.', 1699.00, 50, 'Backpacks', 6),
    (39, 'Zaveri Pearls Gold Plated Kundan & Green Beads Choker Necklace Set', 'Traditional handcrafted Kundan bridal choker set embellished with faux emerald green beads and pearls, paired with matching drop earrings and maang tikka.', 899.00, 30, 'Jewellery', 6),
    (40, 'Titan Neo Analog Blue Dial Men''s Leather Strap Watch', 'Contemporary deep blue sunray dial with silver indices and date aperture at 3 o''clock. Sturdy stainless steel case with scratch-resistant mineral glass and genuine dark brown stitched leather strap.', 3495.00, 35, 'Watches', 6),
    (41, 'Puma Men Solid Regular Fit Windbreaker Zip-Front Hooded Jacket', 'windCELL technology protects against wind chill while maintaining breathability. Full front zipper, elasticated storm cuffs and hem, two secure side zip pockets, lightweight packable design.', 2799.00, 30, 'Jackets', 6),
    (42, 'Jockey Men Super Combed Cotton Ribbed Briefs (Pack of 3)', '100% super combed cotton fabric with StayFresh antibacterial treatment. Soft microfiber elastic waistband prevents marks and chafing, full rear coverage for all-day comfort.', 599.00, 80, 'Briefs, vest', 6),
    (43, 'Metro Women Embellished Block Heel Ankle Strap Sandals', '2.5-inch sturdy block heels with metallic cross-strap upper accented with subtle rhinestone shimmer. Cushioned insole and anti-slip textured resin outsole.', 1990.00, 25, 'Heels & flats', 6),
    (44, 'Bata Men Brown Lightweight Daily Wear Casual Fisherman Sandals', 'Synthetic leather straps with adjustable hook-and-loop velcro closure. Ergonomically molded footbed with arch support and flexible grooved TPR sole for superior grip.', 1299.00, 45, 'Sandals', 6),
    (45, 'Manyavar Men Royal Jacquard Silk Blend Kurta Pyjama Set', 'Regal mandarin collar kurta woven with rich brocade jacquard self-pattern in maroon gold, complemented with comfortable ivory churidar pajama trousers.', 3999.00, 20, 'Kurta pyjama', 6),
    (46, 'Tokyo Talkies Women Korean Oversized Aesthetic Graphic Drop-Shoulder Tee', 'Trendy Seoul streetwear boxy fit t-shirt crafted from heavy 220 GSM combed cotton. Ribbed crew neckline, drop shoulders, and retro typography print on back.', 799.00, 60, 'Korean Store', 6),
    (47, 'US Polo Assn. Men Solid Pique Pure Cotton Slim Fit Polo T-Shirt', 'Classic two-button placket with signature embroidered brand logo on left chest. Breathable pique cotton weave with ribbed collar and sleeve cuffs.', 1499.00, 55, 'Shirts,tees', 6),
    (48, 'Flying Machine Men Multi-Pocket Relaxed Fit Cargo Trousers', 'Durable cotton twill weave with utilitarian 6-pocket configuration. Relaxed thigh fit with tapered drawstring ankles, reinforced seams for rugged casual utility.', 1899.00, 35, 'Jeans, Cargo', 6),
    (49, 'Puma Unisex-Adult Smashic Low-Top Casual Leather Sneakers', 'Clean court-inspired tennis silhouette with soft synthetic leather upper and iconic Puma Formstrip overlay. SoftFoam+ comfort sockliner and non-marking vulcanized rubber outsole.', 2499.00, 40, 'Casual shoes', 6),
    (50, 'Nike Air Monarch IV Men Training & Cross Walking Shoes', 'Durable leather upper with supportive overlays and perforations for airflow. Full-length encapsulated Nike Air-Sole unit provides lightweight cushioning, durable solid rubber outsole.', 4795.00, 25, 'Sports shoes', 6),
    (51, 'Hopscotch Boys & Girls Cotton Printed Nightwear Pajama Set', '100% soft organic cotton sleep suit set with notch collar button-front top and elasticized pajama bottoms printed with adorable space doodles.', 899.00, 45, 'Kids'' Clothing', 6),
    (52, 'Kanjivaram Art Silk Woven Traditional Saree with Rich Pallu', 'Timeless South Indian weave with intricate floral zari jaal across the body, grand contrast temple border, and heavily ornamented pallu. Includes unstitched matching blouse piece.', 2899.00, 30, 'Sarees', 6),
    (53, 'Levi''s Men''s 511 Mid Rise Slim Fit Stretchable Denim Jeans', 'Classic 5-pocket styling in medium indigo wash with whiskering details. Slim from hip to ankle with built-in stretch elastane for all-day mobility and shape retention.', 2399.00, 50, 'Jeans', 6),
    (54, 'Asics Gel-Contend 8 Women Running & Walking Lightweight Shoes', 'Rearfoot GEL technology cushioning improves impact absorption. Engineered breathable mesh upper stretches with the foot''s natural motion, OrthoLite sockliner.', 3499.00, 30, 'Women shoes', 6),
    (55, 'American Tourister 79cm Polypropylene Hard-Sided 8-Wheel Trolley', 'Impact-resistant polypropylene hard shell with textured scratch-resistant finish. Smooth dual 360-degree spinner wheels, integrated TSA 3-digit combination lock, expandable packing volume.', 4499.00, 20, 'Trolley bags', 6),
    (56, 'Ray-Ban Aviator Classic Polarized Metal Frame Sunglasses', 'Iconic teardrop aviator gold metal frame with polarized G-15 crystal green lenses. 100% UV400 radiation protection, eliminates glare, adjustable clear silicone nose pads.', 7490.00, 15, 'Sunglasses', 6),
    (57, 'Fastrack Trendies Quartz Analog Black Dial Women''s Watch', 'Sleek round black dial with rose gold accents and hands. Durable silicon strap with buckle closure, 30m water resistance, Japanese quartz precision movement.', 1295.00, 40, 'Watches', 6),
    (58, 'Allen Solly Men Slim Fit Formal Pure Cotton Spread Collar Shirt', '100% fine cotton yarn with easy-iron finish. Spread collar, long sleeves with mitered button cuffs, curved hemline designed for crisp tuck-in formal styling.', 1699.00, 40, 'Shirts,tees', 6),
    (59, 'Zara Inspired Women Wide-Leg High-Rise Denim Cargo Pants', 'High-waisted wide-leg cut in washed light blue denim. Side utilitarian bellows cargo pockets with flap closures, belt loops, and clean raw hem.', 1999.00, 35, 'Jeans, Cargo', 6),
